// Generated by GitHub Copilot
import { STORE_LEDGER, STORE_SEEN, withStore } from './db';
import type { Ack, LedgerRecord, LedgerStatus, PaymentIntent, Role } from '../protocol/types';
import { logger } from '../ui/logger';

/**
 * Ledger + idempotency store.
 *
 * - markSeen / wasSeen   → replay/idempotency by tx_id.
 * - upsertFromIntent     → create/refresh a CREATED|SENT record for an intent.
 * - applyAck             → transition to ACKED (or FAILED for REJECT).
 * - markStatus           → manual status changes (FAILED, EXPIRED).
 * - listAll / exportJson → audit + export.
 */

export async function wasSeen(tx_id: string): Promise<boolean> {
  const v = await withStore<unknown>(STORE_SEEN, 'readonly', (s) => s.get(tx_id));
  return v != null;
}

export async function markSeen(tx_id: string): Promise<void> {
  await withStore(STORE_SEEN, 'readwrite', (s) => s.put({ tx_id, ts: Date.now() }));
}

export async function getRecord(tx_id: string): Promise<LedgerRecord | undefined> {
  return withStore<LedgerRecord | undefined>(STORE_LEDGER, 'readonly', (s) =>
    s.get(tx_id) as IDBRequest<LedgerRecord | undefined>
  );
}

export async function upsertFromIntent(
  intent: PaymentIntent,
  role: Role,
  initialStatus: Extract<LedgerStatus, 'CREATED' | 'SENT'>,
  trail: string
): Promise<LedgerRecord> {
  const now = Date.now();
  const existing = await getRecord(intent.tx_id);
  const rec: LedgerRecord = existing
    ? {
        ...existing,
        status: existing.status === 'ACKED' ? existing.status : initialStatus,
        ts_updated: now,
        trail: [...existing.trail, `${new Date(now).toISOString()} ${trail}`].slice(-50)
      }
    : {
        tx_id: intent.tx_id,
        role,
        status: initialStatus,
        amount: intent.amount,
        currency: intent.currency,
        ts_created: intent.ts,
        ts_updated: now,
        ttl: intent.ttl,
        intent,
        trail: [`${new Date(now).toISOString()} ${trail}`]
      };
  await withStore(STORE_LEDGER, 'readwrite', (s) => s.put(rec));
  await markSeen(intent.tx_id);
  logger.info('storage', `ledger upsert tx_id=${intent.tx_id} status=${rec.status}`);
  return rec;
}

export async function applyAck(ack: Ack, trail: string): Promise<LedgerRecord | undefined> {
  const rec = await getRecord(ack.ref_tx_id);
  if (!rec) {
    logger.warn('storage', `ACK para tx desconocido: ${ack.ref_tx_id}`);
    return undefined;
  }
  const now = Date.now();
  const next: LedgerRecord = {
    ...rec,
    status: ack.result === 'OK' ? 'ACKED' : 'FAILED',
    ts_updated: now,
    ack,
    trail: [...rec.trail, `${new Date(now).toISOString()} ${trail}`].slice(-50)
  };
  await withStore(STORE_LEDGER, 'readwrite', (s) => s.put(next));
  await markSeen(ack.tx_id);
  return next;
}

export async function markStatus(
  tx_id: string,
  status: LedgerStatus,
  trail: string
): Promise<LedgerRecord | undefined> {
  const rec = await getRecord(tx_id);
  if (!rec) return undefined;
  const now = Date.now();
  const next: LedgerRecord = {
    ...rec,
    status,
    ts_updated: now,
    trail: [...rec.trail, `${new Date(now).toISOString()} ${trail}`].slice(-50)
  };
  await withStore(STORE_LEDGER, 'readwrite', (s) => s.put(next));
  return next;
}

export async function listAll(): Promise<LedgerRecord[]> {
  const out = await withStore<LedgerRecord[]>(STORE_LEDGER, 'readonly', (s) =>
    s.getAll() as IDBRequest<LedgerRecord[]>
  );
  return out.sort((a, b) => b.ts_updated - a.ts_updated);
}

export async function exportJson(): Promise<string> {
  const records = await listAll();
  return JSON.stringify(
    {
      exported_at: new Date().toISOString(),
      count: records.length,
      records
    },
    null,
    2
  );
}
